/**
 * Get the next invoice number for a given year.
 * Format: INV-<year>-<counter> where counter is 4 digits, zero-padded, starting at 0001.
 * @param {string[]} existingNumbers - array of invoice numbers already used (in any order)
 * @param {string} issueDate - issue date in YYYY-MM-DD format
 * @returns {string} the next invoice number
 */
export function nextInvoiceNumber(existingNumbers, issueDate) {
  const year = issueDate.substring(0, 4);
  const prefix = `INV-${year}-`;

  const countersForYear = existingNumbers
    .filter((num) => num.startsWith(prefix))
    .map((num) => {
      const counterStr = num.substring(prefix.length);
      const counter = Number(counterStr);
      return Number.isInteger(counter) && counter > 0 ? counter : 0;
    })
    .filter((c) => c > 0);

  const maxCounter = countersForYear.length > 0 ? Math.max(...countersForYear) : 0;
  const nextCounter = maxCounter + 1;

  return `${prefix}${String(nextCounter).padStart(4, '0')}`;
}

/** Every error code the project returns, with a one-line message. Codes are UPPER_SNAKE_CASE. */
export const ERRORS = {
  AMOUNT_INVALID: 'Amount must be a whole, positive number of cents.',
  CUSTOMER_INVALID: 'A customer needs an id, a name and a valid email.',
  CUSTOMER_NOT_FOUND: 'No customer with that id.',
  DATE_INVALID: 'Issue date must be a valid date in YYYY-MM-DD format.',
  DISCOUNT_INVALID: 'Discount must be a number between 0 and 100.',
  LINE_NOT_FOUND: 'No line with that SKU on the invoice.',
  NO_LINES: 'Invoice must have at least one line.',
  NOT_DRAFT: 'Can only modify invoices with status "draft".',
  NOT_ISSUED: 'Invoice must be issued or partially paid to record a payment.',
  OVERPAYMENT: 'Payment exceeds the amount due.',
  QTY_INVALID: 'Quantity must be a positive integer.',
  TERMS_INVALID: 'Payment terms must be NET14, NET30, or EOM.',
  UNKNOWN_SKU: 'No product with that SKU in the catalogue.',
  VOUCHER_EXISTS: 'Invoice can only have one voucher applied.',
};

/**
 * The message for an error code.
 * @param {string} code
 * @returns {string}
 */
export function message(code) {
  return ERRORS[code] ?? 'Unknown error.';
}

